// Seals a secret with a P-256 key that lives in this Mac's Secure Enclave,
// through the Security framework's C API (called with koffi, so there's no
// native code to build). Sealing is ECIES (ECDH with the Secure Enclave key,
// then AES-GCM), so only that key can unseal it. The key is created outside
// the keychain, so it needs no keychain entitlement and works from any
// binary, `node` included. What we save is the key as wrapped by this Mac's
// Secure Enclave (`kSecAttrTokenOID`), which only it can unwrap: a copy of
// the file can't unseal anything anywhere else.

import { type Koffi, loadKoffi } from './koffi';

export type Pointer = bigint;

const CORE_FOUNDATION =
  '/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation';
const SECURITY = '/System/Library/Frameworks/Security.framework/Security';

const kCFStringEncodingUTF8 = 0x08000100;
const kCFNumberSInt32Type = 3;
const kSecAccessControlPrivateKeyUsage = 1 << 30;
// `SecBase.h` errSecInteractionNotAllowed: the key can't be used while this
// Mac is locked (`kSecAttrAccessibleWhenUnlockedThisDeviceOnly`).
const errSecInteractionNotAllowed = -25308;

/** The Secure Enclave can't use the key while this Mac is locked. */
export class SecureEnclaveLockedError extends Error {}

let api: ReturnType<typeof loadApi> | undefined;

function loadApi(koffi: Koffi) {
  const cf = koffi.load(CORE_FOUNDATION);
  const sec = koffi.load(SECURITY);
  // The value of an exported constant, such as a `CFStringRef`.
  const constant = (lib: typeof cf, name: string): Pointer =>
    koffi.decode(lib.symbol(name), 'void *');

  return {
    koffi,
    CFRelease: cf.func('void CFRelease(void *cf)'),
    CFDictionaryCreateMutable: cf.func(
      'void *CFDictionaryCreateMutable(void *allocator, long capacity, void *keyCallBacks, void *valueCallBacks)'
    ),
    CFDictionarySetValue: cf.func(
      'void CFDictionarySetValue(void *dict, void *key, void *value)'
    ),
    CFDictionaryGetValue: cf.func(
      'void *CFDictionaryGetValue(void *dict, void *key)'
    ),
    CFDataCreate: cf.func(
      'void *CFDataCreate(void *allocator, const uint8_t *bytes, long length)'
    ),
    CFDataGetLength: cf.func('long CFDataGetLength(void *data)'),
    CFDataGetBytePtr: cf.func('void *CFDataGetBytePtr(void *data)'),
    CFNumberCreate: cf.func(
      'void *CFNumberCreate(void *allocator, long type, const int32_t *value)'
    ),
    CFStringCreateWithCString: cf.func(
      'void *CFStringCreateWithCString(void *allocator, const char *str, uint32_t encoding)'
    ),
    CFErrorGetCode: cf.func('long CFErrorGetCode(void *error)'),
    SecAccessControlCreateWithFlags: sec.func(
      'void *SecAccessControlCreateWithFlags(void *allocator, void *protection, unsigned long flags, _Out_ void **error)'
    ),
    SecKeyCreateRandomKey: sec.func(
      'void *SecKeyCreateRandomKey(void *parameters, _Out_ void **error)'
    ),
    SecKeyCreateWithData: sec.func(
      'void *SecKeyCreateWithData(void *keyData, void *attributes, _Out_ void **error)'
    ),
    SecKeyCopyAttributes: sec.func('void *SecKeyCopyAttributes(void *key)'),
    SecKeyCopyPublicKey: sec.func('void *SecKeyCopyPublicKey(void *key)'),
    SecKeyCreateEncryptedData: sec.func(
      'void *SecKeyCreateEncryptedData(void *key, void *algorithm, void *plaintext, _Out_ void **error)'
    ),
    SecKeyCreateDecryptedData: sec.func(
      'void *SecKeyCreateDecryptedData(void *key, void *algorithm, void *ciphertext, _Out_ void **error)'
    ),
    keyCallBacks: cf.symbol('kCFTypeDictionaryKeyCallBacks') as Pointer,
    valueCallBacks: cf.symbol('kCFTypeDictionaryValueCallBacks') as Pointer,
    kCFBooleanFalse: constant(cf, 'kCFBooleanFalse'),
    kSecAttrKeyType: constant(sec, 'kSecAttrKeyType'),
    kSecAttrKeyTypeECSECPrimeRandom: constant(
      sec,
      'kSecAttrKeyTypeECSECPrimeRandom'
    ),
    kSecAttrKeySizeInBits: constant(sec, 'kSecAttrKeySizeInBits'),
    kSecAttrKeyClass: constant(sec, 'kSecAttrKeyClass'),
    kSecAttrKeyClassPrivate: constant(sec, 'kSecAttrKeyClassPrivate'),
    kSecAttrTokenID: constant(sec, 'kSecAttrTokenID'),
    kSecAttrTokenIDSecureEnclave: constant(sec, 'kSecAttrTokenIDSecureEnclave'),
    kSecPrivateKeyAttrs: constant(sec, 'kSecPrivateKeyAttrs'),
    kSecAttrIsPermanent: constant(sec, 'kSecAttrIsPermanent'),
    kSecAttrAccessControl: constant(sec, 'kSecAttrAccessControl'),
    kSecAttrAccessibleWhenUnlockedThisDeviceOnly: constant(
      sec,
      'kSecAttrAccessibleWhenUnlockedThisDeviceOnly'
    ),
    kSecKeyAlgorithmECIESEncryptionCofactorVariableIVX963SHA256AESGCM: constant(
      sec,
      'kSecKeyAlgorithmECIESEncryptionCofactorVariableIVX963SHA256AESGCM'
    ),
  };
}

type Api = ReturnType<typeof loadApi>;

/**
 * Runs `fn` with an `own` function that records each Core Foundation object
 * `fn` creates, and releases them all when it returns or throws.
 */
function withObjects<T>(
  fn: (a: Api, own: (object: Pointer | null, what: string) => Pointer) => T
): T {
  const a = (api ??= loadApi(loadKoffi()));
  const objects: Pointer[] = [];
  try {
    return fn(a, (object, what) => {
      if (!object) {
        throw new Error(`${what} failed.`);
      }
      objects.push(object);
      return object;
    });
  } finally {
    for (const object of objects.reverse()) {
      a.CFRelease(object);
    }
  }
}

/** Calls a function that reports failure with a `CFErrorRef` out argument. */
function check(
  a: Api,
  what: string,
  call: (error: [Pointer | null]) => Pointer | null
): Pointer | null {
  const error: [Pointer | null] = [null];
  const result = call(error);
  if (!result && error[0]) {
    const code = a.CFErrorGetCode(error[0]);
    a.CFRelease(error[0]);
    const message = `${what} failed with error ${code}.`;
    if (Number(code) === errSecInteractionNotAllowed) {
      throw new SecureEnclaveLockedError(message);
    }
    throw new Error(message);
  }
  return result;
}

function dictionary(
  a: Api,
  own: (object: Pointer | null, what: string) => Pointer,
  entries: [Pointer, Pointer][]
): Pointer {
  const dict = own(
    a.CFDictionaryCreateMutable(null, 0, a.keyCallBacks, a.valueCallBacks),
    'CFDictionaryCreateMutable'
  );
  for (const [key, value] of entries) {
    a.CFDictionarySetValue(dict, key, value);
  }
  return dict;
}

function toData(
  a: Api,
  own: (object: Pointer | null, what: string) => Pointer,
  bytes: Buffer | Uint8Array
): Pointer {
  return own(a.CFDataCreate(null, bytes, bytes.length), 'CFDataCreate');
}

function fromData(a: Api, data: Pointer): Buffer {
  const length = Number(a.CFDataGetLength(data));
  if (length === 0) {
    return Buffer.alloc(0);
  }
  // Copy out of the CFData before it's released.
  return Buffer.from(
    new Uint8Array(a.koffi.view(a.CFDataGetBytePtr(data), length))
  );
}

// Not exported by the SDK headers: the attribute that holds a Secure Enclave
// key's wrapped form, which CryptoKit calls `dataRepresentation`.
function tokenOid(
  a: Api,
  own: (object: Pointer | null, what: string) => Pointer
): Pointer {
  return own(
    a.CFStringCreateWithCString(null, 'toid', kCFStringEncodingUTF8),
    'CFStringCreateWithCString'
  );
}

/**
 * Create a key in this Mac's Secure Enclave and seal `secret` with it.
 * Returns the key as wrapped by the Secure Enclave, and the sealed secret.
 */
export function createSecureEnclaveKey(secret: Buffer): {
  wrapped: Buffer;
  sealed: Buffer;
} {
  return withObjects((a, own) => {
    const accessControl = own(
      check(a, 'SecAccessControlCreateWithFlags', error =>
        a.SecAccessControlCreateWithFlags(
          null,
          a.kSecAttrAccessibleWhenUnlockedThisDeviceOnly,
          kSecAccessControlPrivateKeyUsage,
          error
        )
      ),
      'SecAccessControlCreateWithFlags'
    );
    const keySize = own(
      a.CFNumberCreate(null, kCFNumberSInt32Type, Int32Array.of(256)),
      'CFNumberCreate'
    );
    const parameters = dictionary(a, own, [
      [a.kSecAttrKeyType, a.kSecAttrKeyTypeECSECPrimeRandom],
      [a.kSecAttrKeySizeInBits, keySize],
      [a.kSecAttrTokenID, a.kSecAttrTokenIDSecureEnclave],
      [
        a.kSecPrivateKeyAttrs,
        dictionary(a, own, [
          // Not in the keychain, which would need a keychain entitlement.
          [a.kSecAttrIsPermanent, a.kCFBooleanFalse],
          [a.kSecAttrAccessControl, accessControl],
        ]),
      ],
    ]);
    const key = own(
      check(a, 'SecKeyCreateRandomKey', error =>
        a.SecKeyCreateRandomKey(parameters, error)
      ),
      'SecKeyCreateRandomKey'
    );

    const attributes = own(a.SecKeyCopyAttributes(key), 'SecKeyCopyAttributes');
    const wrapped = a.CFDictionaryGetValue(attributes, tokenOid(a, own));
    if (!wrapped) {
      throw new Error("The Secure Enclave didn't return the wrapped key.");
    }

    const publicKey = own(a.SecKeyCopyPublicKey(key), 'SecKeyCopyPublicKey');
    const sealed = own(
      check(a, 'SecKeyCreateEncryptedData', error =>
        a.SecKeyCreateEncryptedData(
          publicKey,
          a.kSecKeyAlgorithmECIESEncryptionCofactorVariableIVX963SHA256AESGCM,
          toData(a, own, secret),
          error
        )
      ),
      'SecKeyCreateEncryptedData'
    );

    return { wrapped: fromData(a, wrapped), sealed: fromData(a, sealed) };
  });
}

/**
 * Unseal what `createSecureEnclaveKey` sealed, with the key `wrapped` by
 * this Mac's Secure Enclave. The Secure Enclave's private key never leaves
 * it. Fails while the Mac is locked.
 */
export function unsealWithSecureEnclaveKey(
  wrapped: Buffer,
  sealed: Buffer
): Buffer {
  return withObjects((a, own) => {
    const attributes = dictionary(a, own, [
      [a.kSecAttrKeyType, a.kSecAttrKeyTypeECSECPrimeRandom],
      [a.kSecAttrKeyClass, a.kSecAttrKeyClassPrivate],
      [a.kSecAttrTokenID, a.kSecAttrTokenIDSecureEnclave],
      [tokenOid(a, own), toData(a, own, wrapped)],
    ]);
    // With a token ID the key comes from the attributes, not `keyData`.
    const key = own(
      check(a, 'SecKeyCreateWithData', error =>
        a.SecKeyCreateWithData(
          toData(a, own, new Uint8Array(0)),
          attributes,
          error
        )
      ),
      'SecKeyCreateWithData'
    );
    const secret = own(
      check(a, 'SecKeyCreateDecryptedData', error =>
        a.SecKeyCreateDecryptedData(
          key,
          a.kSecKeyAlgorithmECIESEncryptionCofactorVariableIVX963SHA256AESGCM,
          toData(a, own, sealed),
          error
        )
      ),
      'SecKeyCreateDecryptedData'
    );
    return fromData(a, secret);
  });
}
